def _regular(indices):
    if len(indices) < 3:
        return False
    gaps = [b - a for a, b in zip(indices, indices[1:])]
    return gaps[0] > 1 and all(g == gaps[0] for g in gaps)


def transform(grid):
    h, w = len(grid), len(grid[0])
    palette = set(v for row in grid for v in row)

    # The tile-fill color is absent from regularly spaced divider rows and
    # columns. Choose the candidate that produces the strongest two-axis grid.
    candidates = []
    for color in palette:
        rows = [r for r in range(h) if color not in grid[r]]
        cols = [c for c in range(w) if all(grid[r][c] != color for r in range(h))]
        if _regular(rows) and _regular(cols):
            candidates.append((len(rows) + len(cols), len(rows) * len(cols), color, rows, cols))
    if not candidates:
        return [row[:] for row in grid]
    _, _, fill, rows, cols = max(candidates)

    junction = [[grid[r][c] for c in cols] for r in rows]
    scaffold = Counter(v for row in junction for v in row).most_common(1)[0][0]
    marks = {}
    for i in range(len(rows) - 1):
        for j in range(len(cols) - 1):
            color = junction[i][j]
            if color != scaffold and all(
                junction[rr][cc] == color
                for rr in (i, i + 1) for cc in (j, j + 1)
